// An in-memory task store.

export function normalizeTags(tags) {
  if (!tags) return [];
  const seen = new Set();
  const out = [];
  for (const tag of tags) {
    if (typeof tag !== 'string') continue;
    const normalized = tag.trim().toLowerCase();
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    out.push(normalized);
  }
  return out;
}

export function createStore() {
  const tasks = [];
  let nextId = 1;
  return {
    add(title, options = {}) {
      const tags = normalizeTags(options && options.tags);
      const task = { id: nextId++, title, done: false, tags };
      tasks.push(task);
      return { ...task, tags: [...task.tags] };
    },
    complete(id) {
      const task = tasks.find((item) => item.id === id);
      if (!task) throw new Error('No task ' + id);
      task.done = true;
      return { ...task, tags: [...task.tags] };
    },
    list(options = {}) {
      const tag = options && options.tag;
      let selected = tasks;
      if (tag !== undefined && tag !== null) {
        const wanted = String(tag).trim().toLowerCase();
        selected = tasks.filter((task) => task.tags.includes(wanted));
      }
      return selected.map((task) => ({ ...task, tags: [...task.tags] }));
    },
  };
}

export function formatTask(task) {
  const tags = task.tags || [];
  const suffix = tags.map((tag) => ' #' + tag).join('');
  return (task.done ? '[x]' : '[ ]') + ' ' + task.id + ' ' + task.title + suffix;
}

import { formatTask } from './format.js';

// Splits argv into plain words and --tag occurrences.
// Throws on an unknown --option or a --tag with no value.
function parseArgs(args) {
  const words = [];
  const tags = [];
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === '--tag') {
      const value = args[i + 1];
      if (value === undefined) throw new Error('--tag needs a value');
      tags.push(value);
      i += 1;
      continue;
    }
    if (arg.startsWith('--')) throw new Error('Unknown option: ' + arg);
    words.push(arg);
  }
  return { words, tags };
}

// Runs one command and returns the lines to print.
export function run(store, argv) {
  const [command, ...rest] = argv;
  if (command === 'add') {
    const { words, tags } = parseArgs(rest);
    return [formatTask(store.add(words.join(' '), { tags }))];
  }
  if (command === 'done') {
    const { words } = parseArgs(rest);
    return [formatTask(store.complete(Number(words[0])))];
  }
  if (command === 'list') {
    const { tags } = parseArgs(rest);
    const options = tags.length ? { tag: tags[0] } : {};
    return store.list(options).map(formatTask);
  }
  throw new Error('Unknown command: ' + command);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { createStore } from '../src/store.js';
import { formatTask } from '../src/format.js';
import { run } from '../src/cli.js';

test('add and complete', () => {
  const store = createStore();
  const task = store.add('Buy milk');
  assert.equal(store.complete(task.id).done, true);
});

test('add without tags gives an empty tags array', () => {
  const store = createStore();
  assert.deepEqual(store.add('Buy milk').tags, []);
});

test('add trims, lowercases and de-duplicates tags', () => {
  const store = createStore();
  const task = store.add('Buy milk', { tags: [' Home ', 'home', 'ERRAND', 'errand', ''] });
  assert.deepEqual(task.tags, ['home', 'errand']);
});

test('list filters by tag without regard to case', () => {
  const store = createStore();
  store.add('Buy milk', { tags: ['home'] });
  store.add('File taxes', { tags: ['errand'] });
  store.add('Sweep', { tags: ['home', 'chore'] });
  assert.deepEqual(
    store.list({ tag: 'HOME' }).map((task) => task.title),
    ['Buy milk', 'Sweep'],
  );
  assert.equal(store.list().length, 3);
});

test('formatTask appends tags after the title', () => {
  const line = formatTask({ id: 1, title: 'Buy milk', done: false, tags: ['home', 'errand'] });
  assert.equal(line, '[ ] 1 Buy milk #home #errand');
  assert.equal(formatTask({ id: 2, title: 'Plain', done: false, tags: [] }), '[ ] 2 Plain');
});

test('cli add accepts repeated --tag and list filters by tag', () => {
  const store = createStore();
  assert.deepEqual(run(store, ['add', 'Buy', 'milk', '--tag', 'home', '--tag', 'errand']), [
    '[ ] 1 Buy milk #home #errand',
  ]);
  run(store, ['add', 'File', 'taxes', '--tag', 'errand']);
  assert.deepEqual(run(store, ['list', '--tag', 'home']), ['[ ] 1 Buy milk #home #errand']);
  assert.deepEqual(run(store, ['list', '--tag', 'ERRAND']), [
    '[ ] 1 Buy milk #home #errand',
    '[ ] 2 File taxes #errand',
  ]);
  assert.equal(run(store, ['list']).length, 2);
});

test('cli throws on unknown option and on --tag without a value', () => {
  const store = createStore();
  assert.throws(() => run(store, ['add', 'Buy', '--x']), /^Error: Unknown option: --x$/);
  assert.throws(() => run(store, ['list', '--tag']), /^Error: --tag needs a value$/);
});

